export const pokemonRouter = createTRPCRouter({
  byId: publicProcedure.input(z.object({ id: z.number() })).query(({ ctx, input }) => {
    return ctx.db.pokemon.findUnique({ where: { id: input.id } })
  }),

  create: publicProcedure.input(pokemonInput).mutation(({ ctx, input }) => {
    return ctx.db.pokemon.create({ data: input })
  }),

  update: publicProcedure.input(pokemonInput.extend({ id: z.number() })).mutation(async ({ ctx, input: { id, ...data } }) => {
    try {
      return await ctx.db.pokemon.update({ where: { id }, data })
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === "P2025") {
        throw new TRPCError({ code: "NOT_FOUND", message: "This Pokemon no longer exists" })
      }
      throw error
    }
  }),
})
